<script setup lang="ts">
import { computed, onMounted, ref } from 'vue'
import { useAuthStore } from '@/stores/auth'
import { ApiError } from '@/services/api'
import { createUser, disableUser, listTeams, listUsers } from '@/services/resources'
import type { Role, Team, User } from '@/types/api'
import PageState from '@/components/PageState.vue'; import StatusBadge from '@/components/StatusBadge.vue'; import ModalDialog from '@/components/ModalDialog.vue'; import IconBase from '@/components/IconBase.vue'
const auth=useAuthStore(), users=ref<User[]>([]), teams=ref<Team[]>([]), loading=ref(true), error=ref(''), modal=ref(false), saving=ref(false), formError=ref(''), disabling=ref('')
const form=ref({email:'',display_name:'',role:'staff' as Role,team_id:'',password:''})
const teamNames=computed(()=>Object.fromEntries(teams.value.map(t=>[t.id,t.name])))
const roleNames={super_admin:'总管理员',team_admin:'团队管理员',staff:'员工'}
async function load(){loading.value=true;error.value='';try{users.value=await listUsers();if(auth.isSuperAdmin)teams.value=await listTeams()}catch(e){error.value=e instanceof ApiError?e.message:'用户载入失败。'}finally{loading.value=false}}
function openCreate(){form.value={email:'',display_name:'',role:'staff',team_id:auth.user?.team_id||'',password:''};formError.value='';modal.value=true}
async function submit(){saving.value=true;formError.value='';try{await createUser({email:form.value.email,display_name:form.value.display_name,role:auth.isSuperAdmin?form.value.role:'staff',team_id:auth.isSuperAdmin?(form.value.role==='super_admin'?null:form.value.team_id):auth.user?.team_id||null,password:form.value.password});modal.value=false;await load()}catch(e){formError.value=e instanceof ApiError?e.message:'创建失败。'}finally{saving.value=false}}
async function disable(user:User){if(!confirm(`确定停用 ${user.display_name}？其现有 Session 将立即失效。`))return;disabling.value=user.id;try{await disableUser(user.id);await load()}catch(e){alert(e instanceof ApiError?e.message:'停用失败。')}finally{disabling.value=''}}
onMounted(load)
</script>
<template><section><header class="page-header"><div><span class="eyebrow">Access control</span><h1>用户管理</h1><p>{{ auth.isSuperAdmin?'管理全平台账号与三级角色。':'仅可查看并管理本团队员工。' }}</p></div><button class="btn btn-primary" @click="openCreate"><IconBase name="plus"/>创建用户</button></header>
<PageState :loading="loading" :error="error" :empty="!users.length" empty-title="暂无可见用户" empty-text="当前授权范围内没有用户记录。" @retry="load"><div class="content-card"><div class="table-wrap"><table><thead><tr><th>用户</th><th>角色</th><th v-if="auth.isSuperAdmin">团队</th><th>状态</th><th>最近登录</th><th class="align-right">操作</th></tr></thead><tbody><tr v-for="user in users" :key="user.id"><td><div class="identity-cell"><span class="avatar avatar-small">{{ user.display_name.slice(0,1) }}</span><div><b>{{ user.display_name }}</b><small>{{ user.email }}</small></div></div></td><td>{{ roleNames[user.role] }}</td><td v-if="auth.isSuperAdmin">{{ user.team_id?teamNames[user.team_id]||'未知团队':'平台级' }}</td><td><StatusBadge :value="user.status"/></td><td>{{ user.last_login_at?new Date(user.last_login_at).toLocaleString('zh-CN'):'从未登录' }}</td><td class="align-right"><button v-if="user.status==='active'&&user.id!==auth.user?.id" class="btn-link danger" :disabled="disabling===user.id" @click="disable(user)">{{ disabling===user.id?'处理中…':'停用' }}</button><span v-else class="muted">—</span></td></tr></tbody></table></div></div></PageState>
<ModalDialog :open="modal" title="创建用户" :description="auth.isSuperAdmin?'选择角色与归属团队。':'团队管理员只能创建本团队员工。'" @close="modal=false"><form class="modal-form" @submit.prevent="submit"><div v-if="formError" class="alert">{{ formError }}</div><div class="form-grid"><label>显示名称<input v-model.trim="form.display_name" required maxlength="120"/></label><label>邮箱<input v-model.trim="form.email" type="email" required autocomplete="off"/></label></div><div class="form-grid"><label>角色<select v-model="form.role" :disabled="!auth.isSuperAdmin"><option value="staff">员工</option><option v-if="auth.isSuperAdmin" value="team_admin">团队管理员</option><option v-if="auth.isSuperAdmin" value="super_admin">总管理员</option></select></label><label v-if="auth.isSuperAdmin&&form.role!=='super_admin'">所属团队<select v-model="form.team_id" required><option value="" disabled>请选择团队</option><option v-for="team in teams" :key="team.id" :value="team.id">{{ team.name }}</option></select></label></div><label>初始密码<input v-model="form.password" type="password" required minlength="12" autocomplete="new-password"/><small>至少 12 个字符；密码不会显示在用户列表或日志中。</small></label><footer><button type="button" class="btn btn-secondary" @click="modal=false">取消</button><button class="btn btn-primary" :disabled="saving">{{ saving?'创建中…':'创建用户' }}</button></footer></form></ModalDialog></section></template>
